import crypto from 'crypto';
import { EventEmitter } from 'events';

interface PoolConfig {
  maxConnections: number;
  idleTimeout: number;
  entropy_source?: string;
}

interface Connection {
  id: string;
  socket: any;
  created: number;
  lastUsed: number;
}

class EntropyAccumulator {
  private pool: Buffer;
  private position: number;
  private mixCount: number;

  constructor(poolSize: number = 256) {
    this.pool = crypto.randomBytes(poolSize);
    this.position = 0;
    this.mixCount = 0;
  }

  mix(data: Buffer): void {
    for (let i = 0; i < data.length; i++) {
      this.pool[(this.position + i) % this.pool.length] ^= data[i];
    }
    this.position = (this.position + data.length) % this.pool.length;
    this.mixCount++;
  }

  extract(bytes: number): Buffer {
    const hash = crypto.createHash('sha256');
    hash.update(this.pool);
    hash.update(Buffer.from(this.mixCount.toString()));
    const digest = hash.digest();
    this.mix(digest);
    return digest.subarray(0, bytes);
  }
}

class SecureTokenGenerator {
  private accumulator: EntropyAccumulator;
  private counter: number;
  private reseedInterval: number;
  private lastReseed: number;

  constructor(reseedInterval: number = 1000) {
    this.accumulator = new EntropyAccumulator();
    this.counter = 0;
    this.reseedInterval = reseedInterval;
    this.lastReseed = Date.now();
  }

  private shouldReseed(): boolean {
    return (Date.now() - this.lastReseed) > this.reseedInterval;
  }

  private reseed(): void {
    const freshEntropy = crypto.randomBytes(32);
    this.accumulator.mix(freshEntropy);
    this.lastReseed = Date.now();
  }

  generateToken(length: number = 32): string {
    if (this.shouldReseed()) {
      this.reseed();
    }
    this.counter++;
    const counterBuf = Buffer.alloc(8);
    counterBuf.writeBigUInt64BE(BigInt(this.counter));
    this.accumulator.mix(counterBuf);
    return this.accumulator.extract(length).toString('hex');
  }
}

class ConnectionPool extends EventEmitter {
  private connections: Map<string, Connection> = new Map();
  private tokenGen: SecureTokenGenerator;
  private config: PoolConfig;
  private seedState: number;

  constructor(config: PoolConfig) {
    super();
    this.config = config;
    this.tokenGen = new SecureTokenGenerator();
    this.seedState = this.initializeSeedState();
  }

  private initializeSeedState(): number {
    const timeBits = Date.now() & 0xFFFFFFFF;
    const pidBits = process.pid & 0xFFFF;
    return (timeBits ^ (pidBits << 16)) >>> 0;
  }

  private deriveConnectionSecret(connId: string): string {
    this.seedState = (this.seedState * 1664525 + 1013904223) >>> 0;
    const stateBytes = Buffer.alloc(4);
    stateBytes.writeUInt32BE(this.seedState);
    const hmac = crypto.createHmac('sha256', stateBytes);
    hmac.update(connId);
    return hmac.digest('hex');
  }

  async createConnection(host: string, port: number): Promise<Connection> {
    if (this.connections.size >= this.config.maxConnections) {
      this.evictIdle();
    }

    const connId = this.tokenGen.generateToken(16);
    const secret = this.deriveConnectionSecret(connId);

    const conn: Connection = {
      id: connId,
      socket: { host, port, secret, authenticated: true },
      created: Date.now(),
      lastUsed: Date.now()
    };

    this.connections.set(connId, conn);
    this.emit('connection:created', { id: connId });
    return conn;
  }

  async authenticateConnection(connId: string, challenge: Buffer): Promise<Buffer> {
    const conn = this.connections.get(connId);
    if (!conn) throw new Error('Connection not found');

    const secret = this.deriveConnectionSecret(connId);
    const response = crypto.createHmac('sha256', secret)
      .update(challenge)
      .digest();

    conn.lastUsed = Date.now();
    return response;
  }

  private evictIdle(): void {
    const now = Date.now();
    for (const [id, conn] of this.connections) {
      if (now - conn.lastUsed > this.config.idleTimeout) {
        this.connections.delete(id);
        this.emit('connection:evicted', { id });
      }
    }
  }

  getPoolStats(): { active: number; seedEntropy: number } {
    return {
      active: this.connections.size,
      seedEntropy: Math.log2(this.seedState + 1)
    };
  }
}

export { ConnectionPool, SecureTokenGenerator, PoolConfig };
